const messageStats = `-- name: MessageStats :one
SELECT
    count(*)::int                                                      AS total,
    count(*) FILTER (WHERE status = 'delivered')::int                  AS delivered,
    count(*) FILTER (WHERE status = 'sent')::int                       AS sent,
    count(*) FILTER (WHERE status = 'failed')::int                     AS failed,
    count(*) FILTER (WHERE status IN ('created', 'queued', 'sending'))::int AS pending,
    COALESCE(avg(EXTRACT(EPOCH FROM (sent_at - created_at))) FILTER (WHERE sent_at IS NOT NULL), 0)::float8 AS avg_send_seconds
FROM messages
WHERE project_id = $1 AND environment = $2 AND direction = 'outbound' AND created_at >= $3
`

type MessageStatsParams struct {
	ProjectID   string
	Environment APIEnvironment
	Since       time.Time
}

type MessageStatsRow struct {
	Total          int32
	Delivered      int32
	Sent           int32
	Failed         int32
	Pending        int32
	AvgSendSeconds float64
}

func (q *Queries) MessageStats(ctx context.Context, arg MessageStatsParams) (MessageStatsRow, error) {
	row := q.db.QueryRow(ctx, messageStats, arg.ProjectID, arg.Environment, arg.Since)
	var i MessageStatsRow
	err := row.Scan(
		&i.Total,
		&i.Delivered,
		&i.Sent,
		&i.Failed,
		&i.Pending,
		&i.AvgSendSeconds,
	)
	return i, err
}

