const waitingMessages = `-- name: WaitingMessages :many
SELECT id FROM messages
WHERE project_id = $1 AND status = 'queued' AND device_id IS NULL AND provider = 'android'
ORDER BY created_at
LIMIT 100
`

// Queued messages not yet assigned to a phone.
func (q *Queries) WaitingMessages(ctx context.Context, projectID string) ([]string, error) {
	rows, err := q.db.Query(ctx, waitingMessages, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
